pous.declaration:
FUNCTION_BLOCK FifoQueue
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status : WORD;
END_VAR
VAR_IN_OUT
    item : INT;
    buffer : ARRAY[*] OF INT;
END_VAR
VAR
    head : DINT := 0;
    tail : DINT := 0;
    count : DINT := 0;
    capacity : DINT;
    enqPrev : BOOL;
    deqPrev : BOOL;
    enqRising : BOOL;
    deqRising : BOOL;
END_VAR

pous.implementation:
capacity := UPPER_BOUND(buffer, 1) - LOWER_BOUND(buffer, 1) + 1;
status := 0;
enqRising := enqueue AND NOT enqPrev;
deqRising := dequeue AND NOT deqPrev;
enqPrev := enqueue;
deqPrev := dequeue;
IF reset THEN
    head := 0;
    tail := 0;
    count := 0;
ELSIF enqRising THEN
    IF count >= capacity THEN
        status := 16#8002;
    ELSE
        buffer[LOWER_BOUND(buffer, 1) + tail] := item;
        tail := tail + 1;
        IF tail >= capacity THEN
            tail := 0;
        END_IF
        count := count + 1;
    END_IF
ELSIF deqRising THEN
    IF count <= 0 THEN
        status := 16#8001;
    ELSE
        item := buffer[LOWER_BOUND(buffer, 1) + head];
        head := head + 1;
        IF head >= capacity THEN
            head := 0;
        END_IF
        count := count - 1;
    END_IF
END_IF
elementCount := count;

